async function getLessons() {
  if (!lessonsPromise) {
    lessonsPromise = fetch("./lessons.json")
      .then(r => { if (!r.ok) throw Error("lessons unavailable"); return r.json(); })
      .then(data => { lessonsData = data.lessons || []; return lessonsData; })
      .catch(error => { lessonsPromise = null; throw error; });
  }
  return lessonsPromise;
}

async function showLessons() {
  stopAudio();
  const token = ++renderToken;
  app.replaceChildren(topline("首页", () => goBack("#home")), heading("情景小课", "正在载入课程…"));
  window.scrollTo(0, 0);
  try {
    const list = await getLessons();
    if (token !== renderToken) return;
    const cards = el("section", "scene-grid");
    list.forEach((lesson, idx) => {
      const done = userStats.completedLessons.includes(lesson.id);
      const card = btn("", "lesson scene-card", () => navigate("#lesson/" + encodeURIComponent(lesson.id)));
      card.append(el("span", "level-icon", lesson.icon || "📘"));
      const info = el("span", "level-details");
      const title = el("span", "lesson-title", (idx + 1) + ". " + lesson.titleZh + " · " + lesson.title);
      if (done) title.append(el("span", "due-pill", "已完成 ✓"));
      info.append(title, el("span", "lesson-meta", (lesson.level || "A1") + " · " + lesson.description + " · " + lesson.wordIds.length + " 词 + 对话"));
      card.append(info, el("span", "arrow", "›"));
      cards.append(card);
    });
    app.replaceChildren(
      topline("首页", () => goBack("#home")),
      heading("情景小课", "每课只需 3 分钟：先认词，再做听音/填空闯关，最后跟读一段真实对话。"),
      cards
    );
  } catch (e) {
    if (token !== renderToken) return;
    app.replaceChildren(topline("首页", () => goBack("#home")), heading("暂时无法载入情景小课", ""), el("p", "empty", "请检查网络后再试一次。"));
  }
}

async function showLesson(lessonId) {
  stopAudio();
  const token = ++renderToken;
  let list = lessonsData;
  if (!list) {
    app.replaceChildren(topline("情景小课", () => goBack("#lessons")), heading("正在载入课程…", ""));
    try { list = await getLessons(); } catch (e) {
      if (token !== renderToken) return;
      app.replaceChildren(topline("情景小课", () => goBack("#lessons")), heading("载入失败", ""), el("p", "empty", "请检查网络后重试。"));
      return;
    }
    if (token !== renderToken) return;
  }
  const lesson = list.find(l => l.id === lessonId);
  if (!lesson) { navigate("#lessons"); return; }

  const lessonWords = lesson.wordIds
    .map(id => curatedById.get(normalizeId(id)))
    .filter(Boolean)
    .slice(0, 6)
    .map(enrichWord);

  let stage = 1; // 1 = intro words, 2 = mixed quiz, 3 = dialogue, 4 = done
  let wordIdx = 0;
  let quizQueue = buildQuizQuestions(lessonWords);
  let quizTotal = quizQueue.length;
  let quizDone = 0;
  let quizFirstTry = 0;
  let quizMissedThisSession = new Set();

  function renderStageNav() {
    const nav = el("div", "stage-nav");
    [["1", "核心词", lessonWords.length + " 个"], ["2", "巩固练", "听音/填空"], ["3", "情景对话", lesson.dialogue.length + " 句"]].forEach(([num, name, sub], i) => {
      const s = btn("", "stage" + (stage === i + 1 ? " is-current" : ""), () => {
        stage = i + 1;
        if (stage === 2 && !quizQueue.length) {
          quizQueue = buildQuizQuestions(lessonWords);
          quizTotal = quizQueue.length;
          quizDone = 0;
        }
        renderLessonStage();
      });
      s.append(el("span", "", stage > i + 1 ? "✓" : num), el("strong", "", name), el("small", "", sub));
      nav.append(s);
    });
    return nav;
  }

  function renderLessonStage() {
    stopAudio();
    if (stage === 1) {
      const w = lessonWords[wordIdx];
      const card = el("article", "wordcard");
      if (w.image) {
        const img = el("img", "photo");
        img.src = w.image;
        img.alt = w.word;
        card.append(img);
      } else {
        const art = el("div", "photo photo-placeholder");
        art.append(el("span", "", w.icon || "📖"));
        card.append(art);
      }
      const info = el("div", "word");
      info.append(el("h1", "", w.word));
      if (w.ipa) info.append(el("p", "ipa-row", w.ipa));
      info.append(el("p", "meaning", w.chinese));
      info.append(btn("🔊 听发音", "sound", () => playWordAudio(w)));
      card.append(info);
      if (w.example) {
        const ex = el("section", "example");
        ex.append(el("small", "", "日常例句"), el("p", "example-en", w.example));
        if (w.exampleChinese) ex.append(el("p", "example-zh", w.exampleChinese));
        ex.append(btn("🔊 听例句", "sound", () => playExampleAudio(w)));
        card.append(ex);
      }
      const navBtns = el("div", "dialogue-actions");
      const nextLabel = wordIdx < lessonWords.length - 1 ? "下一个词 (" + (wordIdx + 1) + "/" + lessonWords.length + ") ›" : "进入第 2 步：巩固练习 ›";
      navBtns.append(btn(nextLabel, "primary", () => {
        awardXp(2);
        learnedWords.add(normalizeId(w.id));
        writeSet(progressKey, learnedWords);
        if (wordIdx < lessonWords.length - 1) {
          wordIdx++;
        } else {
          stage = 2;
        }
        renderLessonStage();
      }));
      if (wordIdx > 0) {
        navBtns.append(btn("‹ 上一个词", "secondary", () => { wordIdx--; renderLessonStage(); }));
      }
      card.append(navBtns);
      app.replaceChildren(topline("情景小课", () => goBack("#lessons"), true), heading(lesson.titleZh + " · " + lesson.title, ""), renderStageNav(), card);
      playWordAudio(w);
      window.scrollTo(0, 0);
      return;
    }

    if (stage === 2) {
      if (!quizQueue.length) {
        stage = 3;
        renderLessonStage();
        return;
      }
      const q = quizQueue[0];
      const bar = el("div", "bar");
      const fill = el("span");
      fill.style.width = Math.round((quizDone / Math.max(1, quizTotal)) * 100) + "%";
      bar.append(fill);

      const card = renderQuizCard(q, (isCorrect) => {
        quizQueue.shift();
        if (isCorrect) {
          quizDone++;
          if (!quizMissedThisSession.has(q.wordId)) {
            quizFirstTry++;
            clearMistake(q.wordId);
          }
          awardXp(4);
        } else {
          quizMissedThisSession.add(q.wordId);
          addMistake(q.wordId);
          quizQueue.push(q);
        }
        renderLessonStage();
      });

      app.replaceChildren(
        topline("情景小课", () => goBack("#lessons"), true),
        heading(lesson.titleZh + " · 巩固练", "进度 " + Math.min(quizDone + 1, quizTotal) + " / " + quizTotal),
        renderStageNav(),
        bar,
        card
      );
      window.scrollTo(0, 0);
      return;
    }

    if (stage === 3) {
      const list = el("section", "dialogues");
      const lineEls = [];
      lesson.dialogue.forEach(d => {
        const line = el("div", "line");
        line.append(el("div", "speaker", d.speaker));
        const body = el("div", "");
        body.append(el("div", "en", d.en), el("div", "zh", d.zh));
        const playBtn = btn("🔊", "mini", () => speak(d.en));
        playBtn.setAttribute("aria-label", "播放对话 " + d.en);
        line.append(body, playBtn);
        lineEls.push(line);
        list.append(line);
      });

      const playAllBtn = btn("▶ 连续播放整段对话", "secondary", () => {
        playDialogueSequence(lesson.dialogue, lineEls, playAllBtn);
      });
      const finishBtn = btn("完成本课 (+15 XP) ✓", "primary", () => {
        stopAudio();
        if (!userStats.completedLessons.includes(lesson.id)) {
          userStats.completedLessons.push(lesson.id);
          writeStats();
        }
        awardXp(15);
        stage = 4;
        renderLessonStage();
      });
      const actions = el("div", "dialogue-actions");
      actions.append(playAllBtn, finishBtn);
      app.replaceChildren(
        topline("情景小课", () => goBack("#lessons"), true),
        heading(lesson.titleZh + " · 情景对话", "先听一遍完整对话，再逐句跟读。"),
        renderStageNav(),
        list,
        actions
      );
      window.scrollTo(0, 0);
      return;
    }

    const done = el("section", "done");
    done.append(
      el("div", "check", "🎉"),
      el("h1", "", "太棒了！本课已完成"),
      el("p", "", "你学习了 " + lessonWords.length + " 个核心词，完成了听音与填空挑战，并练习了“" + lesson.titleZh + "”情景对话。")
    );
    const actions = el("div", "done-actions");
    actions.append(
      btn("返回课程列表", "primary", () => navigate("#lessons")),
      btn("回首页", "secondary", () => navigate("#home"))
    );
    done.append(actions);
    app.replaceChildren(topline("情景小课", () => goBack("#lessons")), done);
    window.scrollTo(0, 0);
  }

  renderLessonStage();
}

function playDialogueSequence(lines, lineEls, triggerBtn) {
  stopAudio();
  let idx = 0;
  if (triggerBtn) triggerBtn.textContent = "🔊 正在播放对话…";
  function step() {
    lineEls.forEach(l => l.classList.remove("is-speaking"));
    if (idx >= lines.length) {
      if (triggerBtn) triggerBtn.textContent = "▶ 连续播放整段对话";
      return;
    }
    const cur = lines[idx];
    lineEls[idx].classList.add("is-speaking");
    if ("speechSynthesis" in window) {
      const u = new SpeechSynthesisUtterance(cur.en);
      u.lang = audioPrefs.accent;
      u.rate = audioPrefs.slow ? 0.84 : 1.0;
      const v = pickEnglishVoice();
      if (v) u.voice = v;
      u.onend = () => {
        idx++;
        dialogueTimer = setTimeout(step, 350);
      };
      u.onerror = () => {
        idx++;
        dialogueTimer = setTimeout(step, 350);
      };
      window.speechSynthesis.speak(u);
    } else {
      showToast("当前浏览器暂不支持语音朗读");
      if (triggerBtn) triggerBtn.textContent = "▶ 连续播放整段对话";
    }
  }
  step();
}

function buildQuizQuestions(wordList) {
  const pool = wordList.length >= 4 ? wordList : words.slice(0, 12).map(enrichWord);
  const questions = [];
  wordList.forEach((w, idx) => {
    const distractors = shuffle(pool.filter(x => normalizeId(x.id) !== normalizeId(w.id))).slice(0, 3);
    while (distractors.length < 3) {
      const extra = enrichWord(words[Math.floor(Math.random() * words.length)]);
      if (normalizeId(extra.id) !== normalizeId(w.id) && !distractors.some(d => d.id === extra.id)) {
        distractors.push(extra);
      }
    }
    const modeCycle = idx % 3;
    if (modeCycle === 0 && w.example && new RegExp("\\b" + w.word.replace(/[.*+?^${}()|[\]\\]/g, "\\$&") + "\\b", "i").test(w.example)) {
      questions.push({
        type: "cloze",
        wordId: normalizeId(w.id),
        wordObj: w,
        options: shuffle([w, ...distractors]).map(o => ({ label: o.word, value: o.word })),
        answer: w.word
      });
    } else if (modeCycle === 1) {
      questions.push({
        type: "listen",
        wordId: normalizeId(w.id),
        wordObj: w,
        options: shuffle([w, ...distractors]).map(o => ({ label: o.chinese, value: o.word })),
        answer: w.word
      });
    } else {
      questions.push({
        type: "zh2en",
        wordId: normalizeId(w.id),
        wordObj: w,
        options: shuffle([w, ...distractors]).map(o => ({ label: o.word, value: o.word })),
        answer: w.word
      });
    }
  });
  return shuffle(questions);
}

function renderQuizCard(q, onContinue) {
  const w = q.wordObj;
  const card = el("article", "quiz-card");
  let answered = false;

  if (q.type === "cloze") {
    card.append(el("span", "quiz-type", "例句填空 · 选择最合适的词"));
    const p = el("p", "quiz-prompt");
    const regex = new RegExp("\\b(" + w.word.replace(/[.*+?^${}()|[\]\\]/g, "\\$&") + ")\\b", "i");
    const parts = w.example.split(regex);
    parts.forEach((part, i) => {
      if (i % 2 === 1) p.append(el("span", "cloze-blank", "______"));
      else p.append(document.createTextNode(part));
    });
    card.append(p);
    if (w.exampleChinese) card.append(el("p", "quiz-sub", w.exampleChinese));
    card.append(btn("🔊 听整句提示", "sound", () => playExampleAudio(w)));
  } else if (q.type === "listen") {
    card.append(el("span", "quiz-type", "听音选义 · 听一听这是什么意思"));
    card.append(el("p", "quiz-prompt", "点击下方按钮听发音"));
    card.append(btn("🔊 播放英语发音", "sound", () => playWordAudio(w)));
    playWordAudio(w);
  } else {
    card.append(el("span", "quiz-type", "看中选英 · 选出对应的英文单词"));
    card.append(el("p", "quiz-prompt", w.chinese));
  }

  const grid = el("div", "choice-grid");
  const feedback = el("div", "feedback-banner");
  feedback.hidden = true;
  const nextBtn = btn("继续 ›", "primary", () => onContinue(lastWasCorrect));
  nextBtn.hidden = true;
  let lastWasCorrect = false;

  q.options.forEach(opt => {
    const cBtn = btn(opt.label, "choice-btn", () => {
      if (answered) return;
      answered = true;
      lastWasCorrect = opt.value === q.answer;
      grid.querySelectorAll("button").forEach(b => { b.disabled = true; });
      if (lastWasCorrect) {
        cBtn.classList.add("is-correct");
        feedback.className = "feedback-banner is-correct";
        feedback.textContent = "✓ 回答正确！ " + w.word + " — " + w.chinese;
      } else {
        cBtn.classList.add("is-wrong");
        grid.querySelectorAll("button").forEach((b, i) => {
          if (q.options[i].value === q.answer) b.classList.add("is-correct");
        });
        feedback.className = "feedback-banner is-wrong";
        feedback.textContent = "正确答案是：" + w.word + "（" + w.chinese + "）。这道题稍后会再出现一次。";
      }
      playWordAudio(w);
      feedback.hidden = false;
      nextBtn.hidden = false;
    });
    grid.append(cBtn);
  });

  card.append(grid, feedback, nextBtn);
  return card;
}

