async function showScene(scene, query = "", selectedLevel = "A1", page = 1, onlyUnlearned = false) {
  stopAudio();
  const token = ++renderToken;
  if (!scenes[scene]) { navigate("#scenes"); return; }
  activeScene = scene;
  if (!dictionaryData) {
    try { await getDictionary(); } catch (e) {}
    if (token !== renderToken) return;
  }
  const all = wordsForScene(scene);
  const list = selectedLevel === "全部" ? all : all.filter(w => w.cefr === selectedLevel);
  const search = el("input", "search");
  search.type = "search";
  search.placeholder = "在本场景搜索英文或中文";
  search.value = query;
  search.setAttribute("aria-label", "搜索英文或中文");
  let filterUnlearned = onlyUnlearned;
  const unlearnedToggle = btn(filterUnlearned ? "只看未学 ✓" : "只看未学", "toggle-chip" + (filterUnlearned ? " is-selected" : ""), () => {
    filterUnlearned = !filterUnlearned;
    unlearnedToggle.textContent = filterUnlearned ? "只看未学 ✓" : "只看未学";
    unlearnedToggle.classList.toggle("is-selected", filterUnlearned);
    page = 1;
    drawRows();
  });
  const toolbar = el("div", "toolbar-row");
  toolbar.append(search, unlearnedToggle);
  const rows = el("section", "word-list");
  const chips = el("div", "filter-chips");
  const levelsToShow = ["A1", "A2", "B1", "B2", "C1", "C2", "全部"];
  levelsToShow.forEach(level => {
    const count = level === "全部" ? all.length : all.filter(w => w.cefr === level).length;
    if (!count) return;
    const chip = btn(level + (level === selectedLevel ? " ✓" : ""), "filter-chip" + (level === selectedLevel ? " is-selected" : ""), () => {
      navigate("#scene/" + encodeURIComponent(scene) + "?level=" + encodeURIComponent(level));
    });
    chips.append(chip);
  });
  const filtered = () => {
    const q = search.value.trim().toLocaleLowerCase();
    return list.filter(w => {
      if (filterUnlearned && learnedWords.has(normalizeId(w.id))) return false;
      return !q || (w.word + " " + w.chinese).toLocaleLowerCase().includes(q);
    });
  };
  let moreButton = null;
  function drawRows() {
    rows.replaceChildren();
    const matches = filtered();
    const visible = matches.slice(0, page * 60);
    if (!visible.length) {
      rows.append(el("p", "empty", filterUnlearned ? "这一组的单词都已记住啦！可以关闭“只看未学”或换个级别。" : "没有找到匹配的单词，试试换个关键词或切换级别。"));
    } else {
      visible.forEach(w => {
        rows.append(makeWordRow(w, w.cefr + (w.ipa ? " · " + w.ipa : ""), () => navigate("#word/" + encodeURIComponent(normalizeId(w.id)))));
      });
    }
    if (moreButton) { moreButton.remove(); moreButton = null; }
    if (matches.length > visible.length) {
      moreButton = btn("再显示 60 个（" + visible.length + " / " + matches.length + "）", "secondary load-more", () => { page++; drawRows(); });
      rows.after(moreButton);
    }
  }
  search.addEventListener("input", () => { page = 1; drawRows(); });
  const topic = el("div", "daily-intro", scenes[scene].description + "。选 A1 入门，再逐步尝试更高等级。");
  const practiceBtn = btn("⚡ 闪卡练习本组（最多 10 词）", "secondary practice-cta", () => {
    navigate("#review/scene/" + encodeURIComponent(scene) + "?level=" + encodeURIComponent(selectedLevel));
  });
  app.replaceChildren(
    topline("场景", () => goBack("#scenes")),
    heading(scene, list.length.toLocaleString() + " 个词 · 当前 " + selectedLevel),
    topic,
    chips,
    practiceBtn,
    toolbar,
    rows
  );
  drawRows();
  window.scrollTo(0, 0);
}

function enrichWord(w) {
  if (isPhraseItem(w)) {
    const p = phrasesById.get(normalizeId(w.id));
    return p ? phraseAsTerm(p) : { ...w, id: normalizeId(w.id), kind: "phrase" };
  }
  const id = normalizeId(w.id || w.word);
  const curated = curatedById.get(id);
  const dictItem = dictById ? dictById.get(id) : null;
  const dictConverted = dictItem ? convertEntry(dictItem) : null;
  const base = dictConverted || {};
  return {
    ...base,
    ...(curated || {}),
    ...w,
    id,
    uk: w.uk || base.uk || (curated ? curated.ipa : "") || "",
    us: w.us || base.us || "",
    ipa: w.ipa || base.ipa || (curated ? curated.ipa : "") || "",
    senses: (w.senses && w.senses.length) ? w.senses : (base.senses || []),
    extraExample: w.extraExample || base.extraExample || null,
    tip: w.tip || base.tip || "",
    fam: (w.fam && w.fam.length) ? w.fam : (base.fam || []),
    syn: (w.syn && w.syn.length) ? w.syn : (base.syn || []),
    ant: (w.ant && w.ant.length) ? w.ant : (base.ant || []),
    image: w.image || curated?.image || null,
    icon: w.icon || curated?.icon || base.icon || "📖",
    wordAudio: w.wordAudio || curated?.wordAudio || null,
    exampleAudio: w.exampleAudio || curated?.exampleAudio || null,
    collocations: (w.collocations && w.collocations.length) ? w.collocations : (curated?.collocations || base.collocations || [])
  };
}

function wordCard(w) {
  const entry = enrichWord(w);
  const id = entry.id;
  const phrase = isPhraseItem(entry);
  const card = el("article", "wordcard");

  if (!phrase && entry.image) {
    const img = el("img", "photo");
    img.src = entry.image;
    img.alt = entry.word + " 图片";
    card.append(img);
  } else {
    const art = el("div", "photo photo-placeholder");
    art.setAttribute("role", "img");
    art.setAttribute("aria-label", entry.word + " 图标");
    art.append(el("span", "", entry.icon || (phrase ? "💬" : "📖")));
    card.append(art);
  }

  const info = el("div", "word");
  const titleEl = el("h1", "", entry.word);
  if (phrase) titleEl.style.fontSize = "clamp(24px, 6.8vw, 34px)";
  info.append(titleEl);

  if (!phrase) {
    const ipaRow = el("div", "ipa-row");
    if (entry.uk && entry.us && entry.uk !== entry.us) {
      const ukTag = el("span", "ipa-tag");
      ukTag.append(el("small", "", "英"), el("span", "", entry.uk));
      const usTag = el("span", "ipa-tag");
      usTag.append(el("small", "", "美"), el("span", "", entry.us));
      ipaRow.append(ukTag, usTag);
    } else if (entry.ipa || entry.uk || entry.us) {
      ipaRow.append(el("span", "ipa-tag", entry.ipa || entry.uk || entry.us));
    }
    if (ipaRow.children.length) info.append(ipaRow);
  }

  if (!phrase && entry.senses && entry.senses.length) {
    const ul = el("ul", "senses-list");
    entry.senses.forEach(s => {
      const li = el("li", "sense-item");
      li.append(el("span", "pos-badge", s.pos || "词义"));
      const body = el("div", "");
      body.append(el("span", "sense-zh", s.zh || ""));
      if (s.en) body.append(el("span", "sense-en", s.en));
      li.append(body);
      ul.append(li);
    });
    info.append(ul);
  } else {
    info.append(el("p", "meaning", entry.chinese || ""));
  }

  const audioRow = el("div", "word-audio-row");
  audioRow.append(btn(phrase ? "🔊 听短句" : "🔊 听单词", "sound", () => playWordAudio(entry)));
  if (entry.cefr) audioRow.append(el("span", "level", entry.cefr));
  info.append(audioRow);
  card.append(info);

  if (entry.tip) {
    const tipBox = el("section", "usage-tip");
    tipBox.append(el("small", "", "💡 用法小贴士 · USAGE TIP"), el("div", "", entry.tip));
    card.append(tipBox);
  }

  if (entry.example) {
    const example = el("section", "example");
    example.append(el("small", "", "日常例句 · EVERYDAY EXAMPLE"), el("p", "example-en", entry.example));
    if (entry.exampleChinese) example.append(el("p", "example-zh", entry.exampleChinese));
    example.append(btn("🔊 听例句", "sound", () => playExampleAudio(entry)));
    card.append(example);
  }

  if (entry.extraExample && entry.extraExample.en) {
    const details = el("details", "extra-example");
    details.append(el("summary", "", "进阶例句 · 查看更多语境"));
    const body = el("div", "example-body");
    body.append(el("p", "example-en", entry.extraExample.en));
    if (entry.extraExample.zh) body.append(el("p", "example-zh", entry.extraExample.zh));
    body.append(btn("🔊 听例句", "sound", () => speak(entry.extraExample.en)));
    details.append(body);
    card.append(details);
  }

  if (entry.collocations?.length) {
    const pair = el("section", "collocations");
    pair.append(el("small", "collocations-label", "常用搭配 · COMMON WORD PAIRS（点按听发音）"));
    const ul = el("ul", "");
    entry.collocations.forEach(p => {
      const li = el("li", "");
      const itemBtn = btn("", "collocation-btn", () => speak(p.en));
      itemBtn.setAttribute("aria-label", "听搭配发音 " + p.en);
      itemBtn.append(el("span", "", p.en), el("small", "", p.zh));
      li.append(itemBtn);
      ul.append(li);
    });
    pair.append(ul);
    card.append(pair);
  }

  if (entry.fam?.length || entry.syn?.length || entry.ant?.length) {
    const rel = el("section", "related-box");
    rel.append(el("small", "related-label", "词族与关联词 · WORD FAMILY & LINKS"));
    const addGroup = (label, items) => {
      if (!items || !items.length) return;
      const g = el("div", "related-group");
      g.append(el("span", "related-group-title", label));
      const wrap = el("div", "chip-wrap");
      items.forEach(rawText => {
        const cleanWord = rawText.replace(/\s*\([^)]*\)\s*/g, "").trim();
        const chip = btn(rawText, "tag-chip", () => {
          const targetId = normalizeId(cleanWord);
          if (curatedById.has(targetId) || (dictById && dictById.has(targetId))) {
            navigate("#word/" + encodeURIComponent(targetId));
          } else {
            navigate("#lookup/" + encodeURIComponent(cleanWord));
          }
        });
        wrap.append(chip);
      });
      g.append(wrap);
      rel.append(g);
    };
    addGroup("词族", entry.fam);
    addGroup("近义词", entry.syn);
    addGroup("反义词", entry.ant);
    card.append(rel);
  }

  const badge = el("span", "scene-tag", (entry.scene || "词典查询") + (entry.cefr ? " · " + entry.cefr : ""));
  card.append(badge);

  const saveButton = btn("", "primary save-term", () => {
    const nowSaved = toggleSaved(entry);
    updateSaveButton(nowSaved);
    showToast(nowSaved ? "已收藏到“我的学习”" : "已从“我的学习”移除");
  });
  function updateSaveButton(saved) {
    saveButton.textContent = saved ? "已加入我的学习 ✓（点此取消）" : "收藏到我的学习";
    saveButton.setAttribute("aria-pressed", String(saved));
  }
  updateSaveButton(isSaved(id));
  card.append(saveButton);

  const marked = btn("", "secondary save-term", () => {
    if (phrase) {
      if (learnedPhrases.has(id)) learnedPhrases.delete(id);
      else { learnedPhrases.add(id); awardXp(2); }
      writeSet(phraseProgressKey, learnedPhrases);
      updateMarkedButton(learnedPhrases.has(id));
    } else {
      if (learnedWords.has(id)) learnedWords.delete(id);
      else { learnedWords.add(id); awardXp(2); }
      writeSet(progressKey, learnedWords);
      updateMarkedButton(learnedWords.has(id));
    }
  });
  function updateMarkedButton(learned) {
    marked.textContent = learned ? (phrase ? "已学会这句 ✓" : "已记住这个词 ✓") : "标记为学会";
    marked.setAttribute("aria-pressed", String(learned));
  }
  updateMarkedButton(phrase ? learnedPhrases.has(id) : learnedWords.has(id));
  card.append(marked);
  return card;
}

async function showWordById(id) {
  stopAudio();
  const token = ++renderToken;
  const key = normalizeId(id);
  const phraseItem = phrasesById.get(key);
  let w = phraseItem
    ? phraseAsTerm(phraseItem)
    : curatedById.get(key) || savedTerms.find(t => normalizeId(t.id) === key) || (dictById ? (dictById.get(key) ? convertEntry(dictById.get(key)) : null) : null);

  if (!w) {
    app.replaceChildren(topline("返回", () => goBack("#home"), true), heading("正在载入词条…", ""));
    try { await getDictionary(); } catch (e) {}
    if (token !== renderToken) return;
    const item = dictById ? dictById.get(key) : null;
    if (item) w = convertEntry(item);
  }
  if (!w) {
    app.replaceChildren(topline("首页", () => navigate("#home")), heading("找不到这个词条", ""), el("p", "empty", "可以去查词翻译重新搜索。"));
    return;
  }
  const fallback = isPhraseItem(w) ? "#phrases" : (w.scene && scenes[w.scene] ? "#scene/" + encodeURIComponent(w.scene) : "#home");
  app.replaceChildren(topline("返回", () => goBack(fallback), true), wordCard(w));
  window.scrollTo(0, 0);

  if (!isPhraseItem(w) && !dictById) {
    getDictionary().then(() => {
      if (token !== renderToken) return;
      if (dictById && dictById.has(key)) {
        app.replaceChildren(topline("返回", () => goBack(fallback), true), wordCard(w));
      }
    }).catch(() => {});
  }
}

function todayIndex() {
  const now = new Date();
  const localDay = Math.floor(Date.UTC(now.getFullYear(), now.getMonth(), now.getDate()) / 86400000);
  const groups = Math.ceil(phrases.length / 10);
  return ((localDay % groups) + groups) % groups;
}

function showDailyPhrases(params = new URLSearchParams()) {
  stopAudio();
  const totalGroups = Math.ceil(phrases.length / 10);
  const todayGroup = todayIndex();
  const selectedScene = params.get("scene") || "";
  const rawGroup = parseInt(params.get("group") || "", 10);
  const activeGroup = Number.isFinite(rawGroup) && rawGroup >= 1 && rawGroup <= totalGroups ? rawGroup - 1 : todayGroup;

  const currentList = selectedScene
    ? phrases.filter(p => p.scene === selectedScene)
    : phrases.slice(activeGroup * 10, activeGroup * 10 + 10);

  const chips = el("div", "filter-chips");
  const todayChip = btn(
    "今日推荐" + (!selectedScene && activeGroup === todayGroup ? " ✓" : ""),
    "filter-chip" + (!selectedScene && activeGroup === todayGroup ? " is-selected" : ""),
    () => navigate("#phrases")
  );
  chips.append(todayChip);
  phraseScenes.forEach(sc => {
    const chip = btn(
      sc + (selectedScene === sc ? " ✓" : ""),
      "filter-chip" + (selectedScene === sc ? " is-selected" : ""),
      () => navigate("#phrases?scene=" + encodeURIComponent(sc))
    );
    chips.append(chip);
  });

  let navBar = null;
  if (!selectedScene) {
    navBar = el("div", "phrase-nav");
    const prevGroup = ((activeGroup - 1 + totalGroups) % totalGroups) + 1;
    const nextGroup = ((activeGroup + 1) % totalGroups) + 1;
    navBar.append(
      btn("‹ 上一组", "", () => navigate("#phrases?group=" + prevGroup)),
      el("span", "phrase-nav-label", "第 " + (activeGroup + 1) + " / " + totalGroups + " 组" + (activeGroup === todayGroup ? "（今日）" : "")),
      btn("下一组 ›", "", () => navigate("#phrases?group=" + nextGroup))
    );
  }

  const intro = el("div", "daily-intro");
  function updateIntro() {
    const done = currentList.filter(p => learnedPhrases.has(p.id)).length;
    if (selectedScene) {
      intro.textContent = "主题“" + selectedScene + "”共 " + currentList.length + " 句：已学会 " + done + " / " + currentList.length + " 句。点击“收藏”可存入“我的学习”做闪卡复习。";
    } else {
      intro.textContent = "先听一听，再跟着读。本组已学会 " + done + " / " + currentList.length + " 句。有用的句子可以收藏进“我的学习”。";
    }
  }
  updateIntro();

  const practiceHref = selectedScene
    ? "#review/phrases?scene=" + encodeURIComponent(selectedScene)
    : "#review/phrases?group=" + (activeGroup + 1);
  const practiceBtn = btn("⚡ 闪卡练习这 " + currentList.length + " 句", "secondary practice-cta", () => navigate(practiceHref));

  const list = el("section", "phrase-list");
  currentList.forEach(p => {
    const isDone = learnedPhrases.has(p.id);
    const saved = isSaved(p.id);
    const row = el("article", "phrase-row" + (isDone ? " learned" : ""));
    const head = el("div", "phrase-head");
    const text = el("div", "phrase-text");
    text.append(el("strong", "", p.en), el("small", "", p.zh));
    head.append(text, el("span", "phrase-scene-pill", p.scene));

    const controls = el("div", "phrase-controls");
    const audio = btn("🔊 听发音", "", () => speak(p.en));
    audio.setAttribute("aria-label", "播放英语发音 " + p.en);

    const saveBtn = btn(saved ? "⭐ 已收藏" : "☆ 收藏", "phrase-save-btn" + (saved ? " is-saved" : ""), () => {
      const nowSaved = toggleSaved(phraseAsTerm(p));
      saveBtn.textContent = nowSaved ? "⭐ 已收藏" : "☆ 收藏";
      saveBtn.classList.toggle("is-saved", nowSaved);
      saveBtn.setAttribute("aria-pressed", String(nowSaved));
      showToast(nowSaved ? "已收藏短句到“我的学习”" : "已取消收藏短句");
    });
    saveBtn.setAttribute("aria-pressed", String(saved));

    const learned = btn(isDone ? "学会了 ✓" : "学会了", "", () => {
      const nowLearned = !learnedPhrases.has(p.id);
      if (nowLearned) { learnedPhrases.add(p.id); awardXp(2); }
      else learnedPhrases.delete(p.id);
      writeSet(phraseProgressKey, learnedPhrases);
      row.classList.toggle("learned", nowLearned);
      learned.textContent = nowLearned ? "学会了 ✓" : "学会了";
      learned.setAttribute("aria-pressed", String(nowLearned));
      updateIntro();
    });
    learned.setAttribute("aria-pressed", String(isDone));

    controls.append(audio, saveBtn, learned);
    row.append(head, controls);
    list.append(row);
  });

  const subtitle = selectedScene
    ? selectedScene + " · 共 " + currentList.length + " 句"
    : "共 " + phrases.length + " 句 · 14 组日常与出行场景";
  const children = [topline("首页", () => goBack("#home"), true), heading("今日10句", subtitle), chips];
  if (navBar) children.push(navBar);
  children.push(intro, practiceBtn, list);
  app.replaceChildren(...children);
  const activeChip = chips.querySelector(".is-selected");
  if (activeChip && typeof activeChip.scrollIntoView === "function") activeChip.scrollIntoView({ inline: "center", block: "nearest" });
  window.scrollTo(0, 0);
}

async function getDictionary() {
  if (!dictionaryPromise) {
    dictionaryPromise = fetch("./dictionary.json")
      .then(r => { if (!r.ok) throw Error("dictionary unavailable"); return r.json(); })
      .then(data => {
        dictionaryData = data;
        dictById = new Map();
        data.forEach(item => {
          dictById.set(normalizeId(item.id || item.w), item);
          dictById.set(normalizeId(item.w), item);
        });
        return data;
      })
      .catch(error => { dictionaryPromise = null; throw error; });
  }
  return dictionaryPromise;
}

function convertEntry(item) {
  const id = normalizeId(item.id || item.w);
  const curated = curatedById.get(id);
  const ex = item.ex?.[0] || {};
  const extra = item.ex?.[1] || null;
  const theme = Object.entries(themes).find(([, topics]) => topics.includes(item.topic))?.[0] || "更多主题";
  return {
    id,
    word: item.w,
    uk: item.uk || "",
    us: item.us || "",
    ipa: item.uk || item.us || "",
    senses: item.senses || [],
    chinese: (item.senses || []).map(s => s.zh).filter(Boolean).join("；"),
    cefr: item.cefr,
    scene: theme,
    example: ex.en || "",
    exampleChinese: ex.zh || "",
    extraExample: extra,
    tip: item.tip || "",
    fam: item.fam || [],
    syn: item.syn || [],
    ant: item.ant || [],
    image: curated?.image || null,
    icon: curated?.icon || "📘",
    wordAudio: curated?.wordAudio || null,
    exampleAudio: curated?.exampleAudio || null,
    collocations: (item.col || []).slice(0, 3).map(s => { const parts = s.split("｜"); return { en: parts[0], zh: parts[1] || "" }; })
  };
}

